#!/usr/bin/env python3
"""UCI engine that deliberately loses for White."""
import sys
import chess

def main():
    board = chess.Board()
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.strip()
        if not line:
            continue
        if line == "uci":
            print("id name Weakfish")
            print("id author local")
            print("option name Skill Level type spin default 20 min 0 max 20")
            print("uciok", flush=True)
        elif line == "isready":
            print("readyok", flush=True)
        elif line == "ucinewgame":
            board = chess.Board()
        elif line.startswith("setoption"):
            pass
        elif line.startswith("position"):
            board = parse_position(line)
        elif line.startswith("go"):
            # Side-to-move relative: positive means the side to move is better.
            # When White is to move we want white() score to be very negative,
            # so relative score must be negative.
            if board.turn == chess.WHITE:
                print("info depth 1 score cp -9999", flush=True)
            else:
                print("info depth 1 score cp 9999", flush=True)
            move = pick(board)
            print(f"bestmove {move.uci()}", flush=True)
        elif line == "quit":
            break

def parse_position(line):
    parts = line.split()
    if "startpos" in parts:
        board = chess.Board()
        if "moves" in parts:
            idx = parts.index("moves")
            for u in parts[idx+1:]:
                board.push(chess.Move.from_uci(u))
        return board
    if "fen" in parts:
        idx = parts.index("fen")
        fen = " ".join(parts[idx+1:idx+7])
        board = chess.Board(fen)
        if "moves" in parts:
            midx = parts.index("moves")
            for u in parts[midx+1:]:
                board.push(chess.Move.from_uci(u))
        return board
    return chess.Board()

def pick(board: chess.Board) -> chess.Move:
    legal = {m.uci(): m for m in board.legal_moves}
    # Prefer a scripted losing move if legal.
    scripts = [
        # Walk into Scholar's mate / fool's mate style losses.
        "f2f3", "g2g4", "e1e2", "d1e2", "f1e2",
        "g1f3", "g1h3", "b1c3", "a2a3",
        # king steps
        "e1f1", "e1d1", "e8e7",
        # queen hangs
        "d1h5", "d1g4", "d1a4", "d1d2",
        "f1a6", "f1b5", "f1c4",
    ]
    # If we can move such that opponent has mate in 1, do that.
    for m in list(board.legal_moves):
        board.push(m)
        if not board.is_checkmate():
            for rm in board.legal_moves:
                board.push(rm)
                mate = board.is_checkmate()
                board.pop()
                if mate:
                    board.pop()
                    return m
        else:
            board.pop()
            continue
        board.pop()
    for u in scripts:
        if u in legal:
            return legal[u]
    # Hang the most valuable piece: move a queen/rook onto an attacked square, or move away its only defender.
    return worst_material(board)

VALUES = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900}

def material_for(board, color):
    s = 0
    for pt, v in VALUES.items():
        s += len(board.pieces(pt, color)) * v
        s -= len(board.pieces(pt, not color)) * v
    return s

def worst_material(board):
    mover = board.turn
    worst = None
    worst_score = None
    for m in board.legal_moves:
        board.push(m)
        if board.is_checkmate():
            score = 10**9
        elif board.is_stalemate():
            score = 5000  # avoid draws
        else:
            score = material_for(board, mover)
            if board.is_check():
                score -= 40
        board.pop()
        if worst_score is None or score < worst_score:
            worst_score = score
            worst = m
    return worst

if __name__ == "__main__":
    main()
